import { formatdisplayDate } from "@/JsonFiles/DateFormate.js";
import { list_assigned_tasks } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  // Components
  components: {
    AssignByMe
  },
  // Props
  props: {
    selectedFilter: {
      type: String,
      default: "ALL"
    },
    searchValue: {
      type: String,
      default: ""
    },
    selectedStatusFilter: {
      type: String,
      default: "ALL"
    }
  },
  // Data
  data() {
    return {
      // Table properties
      fixed: true,
      tableLoading: false,
      tableData: [],
      tableHeight: 0,
      // Table headers
      headers: [{
        title: "Task Details",
        key: "task_name",
        sortable: false
      }, {
        title: "Task Frequency",
        key: "enabled_recursion",
        sortable: false
      }, {
        title: "Assign To",
        key: "task_assign_to",
        sortable: false
      }, {
        title: "Assigned On",
        key: "task_created_on",
        sortable: false
      }, {
        title: "Completion Date",
        key: "task_completion_date",
        sortable: false
      }, {
        title: "Task Progress",
        key: "task_completion_percentage",
        sortable: false
      }, {
        title: "Status",
        key: "task_progress_status",
        sortable: false
      }, {
        title: "Actions",
        key: "actions",
        sortable: false
      }],
      // Dialog states
      componentcheck: 0,
      assignByMeDialog: false,
      rowInfo: {},
      // Data arrays
      masterData: [],
      selectedCard: null,
      // Pagination properties
      currentPage: 1,
      itemsPerPage: 20,
      pagination: {
        itemsPerPage: 20,
        page: 1
      },
      // Filter properties
