      showFilterDrawer: false,
      localSelectedStatusFilter: "ALL"
    };
  },
  // Lifecycle hooks
  created() {
    const storedData = localStorage.getItem("recurssionEnabled");
    this.list_task_assigned_by_me(storedData);
  },
  mounted() {
    this.tableHeight = window.innerHeight - 260;
    this.emitFilterCounts();
  },
  // Watchers
  watch: {
    searchValue() {
      this.currentPage = 1;
    },
    filteredTasks() {
      if (this.currentPage > this.pageCount) {
        this.currentPage = 1;
      }
    },
    selectedStatusFilter: {
      handler(newVal) {
        this.localSelectedStatusFilter = newVal;
        this.emitFilterCounts();
      },
      immediate: true
    }
  },
  // Computed properties
  computed: {
    overdueTaskCount() {
      if (!this.masterData || this.masterData.length === 0) return 0;
      const today = new Date().toISOString().split("T")[0];
      return this.masterData.filter(task => task.task_completion_date && this.formatedatedisplay(task.task_completion_date) < today && task.task_progress_status === "INPROGRESS").length;
    },
    upcomingTaskCount() {
      if (!this.masterData || this.masterData.length === 0) return 0;
      const today = new Date().toISOString().split("T")[0];
      return this.masterData.filter(task => task.task_completion_date && this.formatedatedisplay(task.task_completion_date) >= today && task.task_progress_status === "INPROGRESS").length;
    },
    onholdTaskCount() {
      if (!this.masterData || this.masterData.length === 0) return 0;
      return this.masterData.filter(task => task.task_progress_status === "HOLD").length;
    },
    completedTaskCount() {
      if (!this.masterData || this.masterData.length === 0) return 0;
      return this.masterData.filter(task => task.task_progress_status === "COMPLETED").length;
    },
    withdrawnTaskCount() {
      if (!this.masterData || this.masterData.length === 0) return 0;
      return this.masterData.filter(task => task.task_progress_status === "WITHDRAWN" || task.task_progress_status === "WITHDRAW").length;
    },
    totalTaskCount() {
      return this.masterData ? this.masterData.length : 0;
    },
    sortedTasks() {
      const today = new Date().toISOString().split("T")[0];
      let filtered = [...this.masterData];
      if (this.selectedFilter === "OVERDUE") {
        filtered = filtered.filter(task => task.task_completion_date && task.task_completion_date < today && task.task_progress_status === "INPROGRESS");
      } else if (this.selectedFilter === "UPCOMING") {
        filtered = filtered.filter(task => task.task_completion_date && task.task_completion_date >= today && task.task_progress_status === "INPROGRESS");
      } else if (this.selectedFilter === "COMPLETED") {
        filtered = filtered.filter(task => task.task_progress_status === "COMPLETED");
      } else if (this.selectedFilter === "HOLD") {
        filtered = filtered.filter(task => task.task_progress_status === "HOLD");
      }

      // Dynamic sort: current month first, then previous month, then others
      return filtered.sort((a, b) => {
        const getMonth = dateStr => {
          if (!dateStr) return 0;
          const parts = dateStr.split("-");
          return parseInt(parts[1], 10) || 0;
        };
        const currentDate = new Date();
        const currentMonth = currentDate.getMonth() + 1;
        const previousMonth = currentMonth === 1 ? 12 : currentMonth - 1;
        const aMonth = getMonth(a.task_completion_date);
        const bMonth = getMonth(b.task_completion_date);

        // Current month first
        if (aMonth === currentMonth && bMonth !== currentMonth) return -1;
        if (aMonth !== currentMonth && bMonth === currentMonth) return 1;

        // Previous month next
        if (aMonth === previousMonth && bMonth !== previousMonth) return -1;
        if (aMonth !== previousMonth && bMonth === previousMonth) return 1;

        // Within the same month, sort by completion date in descending order
        if (aMonth === bMonth) {
          if (a.task_completion_date > b.task_completion_date) return -1;
          if (a.task_completion_date < b.task_completion_date) return 1;
        }

        // For different months, sort by date descending
        if (a.task_completion_date > b.task_completion_date) return -1;
        if (a.task_completion_date < b.task_completion_date) return 1;
        return 0;
      });
    },
    filteredTasks() {
      let tasks = this.sortedTasks;
      if (this.localSelectedStatusFilter !== "ALL") {
        tasks = tasks.filter(t => t.task_progress_status === this.localSelectedStatusFilter);
      }
      if (!this.searchValue) return tasks;
      const s = this.searchValue.toLowerCase();
      return tasks.filter(item => item.task_name && item.task_name.toLowerCase().includes(s) || item.task_description && item.task_description.toLowerCase().includes(s));
    },
    pageCount() {
      return Math.ceil(this.filteredTasks.length / this.itemsPerPage);
    },
    paginatedTasks() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      return this.filteredTasks.slice(start, start + this.itemsPerPage);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  // Methods
  methods: {
    // Data fetching methods
    async list_task_assigned_by_me(value) {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_assigned_tasks, {
          input: {
            limit: 200,
            nextToken: null
          }
        }));
        this.tableLoading = false;
        this.tableData = [];
        var response = JSON.parse(result.data.list_assigned_tasks);
        if (response.Status === "SUCCESS") {
          this.masterData = response.data;
          this.tableData = response.data;
          this.tableLoading = false;
        } else {
          this.masterData = [];
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.tableLoading = false;
        this.masterData = [];
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    // Pagination methods
    handle_pagination() {
      if (this.nextToken) {
        this.list_task_assigned_by_me();
      }
    },
    // Dialog management methods
    handleRowClick(item) {
      this.componentcheck = 1;
      this.rowInfo = item;
      this.assignByMeDialog = true;
    },
    openAssignByMeDialog(item) {
      this.componentcheck = 1;
      this.rowInfo = item;
      this.assignByMeDialog = true;
    },
    // Filter methods
    clearStatusFilter() {
      this.localSelectedStatusFilter = "ALL";
      this.filterMenu = false;
      this.emitFilterCounts();
    },
    handleFilterChange() {
      this.currentPage = 1;
      this.$emit("filter-changed", this.localSelectedStatusFilter);
      this.emitFilterCounts();
    },
    emitFilterCounts() {
      const activeFiltersCount = this.localSelectedStatusFilter !== "ALL" ? 1 : 0;
      this.$emit("active-filters-count", activeFiltersCount);
    },
    clearFilter() {
      this.localSelectedStatusFilter = "ALL";
      this.currentPage = 1;
      this.showFilterDrawer = false;
      this.emitFilterCounts();
    },
    applyFilter() {
      this.showFilterDrawer = false;
      this.currentPage = 1;
    },
    openFilterDrawer() {
      this.showFilterDrawer = true;
    },
    // Utility methods
    fetch_org_format(value) {
      if (value != undefined) {
        return formatdisplayDate(value);
      }
    },
    getdateformate(formatMap) {
      var check_date = "yyyy-MM-dd";
      return check_date.replace(/DD|MMM|YYYY|MM/gi, matched => formatMap[matched]);
    },
    formatedatedisplay(dateString) {
      if (dateString == "N/A") {
        return dateString;
      }
      const [year, month, day] = dateString.split("-");
      if (day == undefined) {
        return dateString;
      }
      const dayPadded = day.padStart(2, "0");
      const numericMonthPadded = month.padStart(2, "0");
      const fullMonthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
      const fullMonthName = fullMonthNames[parseInt(month, 10) - 1];
      const formatMap = {
        dd: dayPadded,
        MM: numericMonthPadded,
        yyyy: year,
        MMM: fullMonthName
      };
      return this.getdateformate(formatMap);
    },
    fetch_value(val) {
      return format_Date(val / 1000);
    },
    // Styling methods
    getStatusColor(status) {
      switch (status) {
        case "COMPLETED":
          return "green";
        case "INPROGRESS":
          return "orange";
        case "HOLD":
          return "red";
        case "WITHDRAWN":
          return "primary";
        case "WITHDRAW":
          return "primary";
        case "ASSIGNED":
          return "brown";
        default:
          return "default";
      }
    },
    truncateText(text) {
      if (!text) return "";
      const maxLength = 40;
      if (text.length > maxLength) {
        return text.slice(0, maxLength) + "...";
      }
      return text;
    },
    // Notification methods
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.assignByMeDialog = false;
      this.list_task_assigned_by_me();
    }
  }
